    with open(path) as f:
        data = json.load(f)

    pairs = set()
    if 'consensus_detail' in data:
        for item in data['consensus_detail']:
            pairs.add(item['pair'])

    has_ppl = any('ppl' in p or 'perplexity' in p for p in pairs)
    has_mauve = any('mauve' in p for p in pairs)
    has_effrank = any('rank' in p.lower() for p in pairs)
    status = 'STANDARD' if (has_mauve and not has_ppl) else 'NON-STANDARD'
    flags = []
    if has_ppl: flags.append('has_ppl')
    if not has_mauve: flags.append('no_mauve')
    if has_effrank: flags.append('has_effrank')
    flag_str = ' (' + ', '.join(flags) + ')' if flags else ''
    print(f'{name}: {status}{flag_str} | {sorted(pairs)}')
